#include <conio.h>
int add(); /* function prototype */
int val1, val2, val3; /*These are global variables */
int add()
{
int sum; // here, sum is local variable
sum = val1 + val2 + val3;
return sum;
}
int main()
{
int total; //here, total is local variable
val1 = 10;
val2 = 20;
val3 = 30;
total = add();
cout<<"The sum of the three global variables="<<total;
getch();
return 0;
}

